ROWS = [
dict(id="T099", d="IPS", t="Critical exponents of the contact process and the universality of directed percolation",
 s="For the nearest-neighbour contact process on Z with recovery rate 1 and infection rate λ, the critical exponents exist: the stationary density satisfies ρ(λ) = (λ − λ_c)^{β+o(1)} as λ ↓ λ_c, and the spatial and temporal correlation lengths diverge like (λ − λ_c)^{−ν_⊥+o(1)} and (λ − λ_c)^{−ν_∥+o(1)}. Moreover the same exponents govern oriented bond and site percolation on the two-dimensional oriented lattice and every finite-range contact process on Z.",
 c="The general form, the Janssen–Grassberger conjecture, puts every model with a single absorbing state, short-range interactions and no extra symmetry or conservation law in this class; it has no agreed mathematical definition, so the row names models. Numerical values in 1+1 dimensions are β ≈ 0.2765, ν_⊥ ≈ 1.0969, ν_∥ ≈ 1.7339 (Jensen, J. Phys. A 32 (1999) 5233); no exact values are conjectured.",
 src="H. K. Janssen, On the nonequilibrium phase transition in reaction–diffusion systems with an absorbing stationary state, Z. Phys. B 42 (1981); P. Grassberger, On phase transitions in Schlögl's second model, Z. Phys. B 47 (1982); T. M. Liggett, Stochastic Interacting Systems: Contact, Voter and Exclusion Processes (Springer, 1999)",
 why="Directed percolation is the canonical non-equilibrium phase transition, the absorbing-state counterpart of the Ising model. It has been seen in experiments (turbulent liquid crystals, Takeuchi–Kuroda–Chaté–Sano 2007), and nothing about its low-dimensional exponents is proved.",
 st="The critical contact process dies out (Bezuidenhout–Grimmett 1990). Mean-field behaviour holds above the upper critical dimension 4, for spread-out oriented percolation (Nguyen–Yang 1993; van der Hofstad–Slade 2003) and for the spread-out contact process (Sakai, J. Stat. Phys. 104 (2001) 111). In 1+1 dimensions no exponent is known to exist, and a scaling limit near criticality has not been constructed.",
 n="Statement revised after the w673 audit (14 Oct)."),
dict(id="T100", d="IPS", t="Avalanche exponents of the two-dimensional abelian sandpile",
 s="For the abelian sandpile on Z^2 in its stationary measure (the infinite-volume limit of the uniform measure on recurrent configurations), add a grain at the origin and stabilize. Prove that the number S of topplings satisfies P(S ≥ s) = s^{1−τ+o(1)} for an exponent τ, prove the corresponding power laws for the radius (the largest distance from the origin of a toppled site) and the duration (the number of rounds of parallel toppling, in which every unstable site topples at once), and identify the exponents.",
 c="Priezzhev, Ktitarev and Ivashkevich predicted τ = 6/5 from a decomposition of avalanches into waves of topplings (Phys. Rev. Lett. 76 (1996) 2093). Numerical studies find multifractal rather than simple finite-size scaling of the avalanche size (Tebaldi–De Menech–Stella 1999), so whether a single exponent exists is part of the question.",
 src="P. Bak, C. Tang and K. Wiesenfeld, Self-organized criticality: an explanation of 1/f noise, Phys. Rev. Lett. 59 (1987); D. Dhar, Self-organized critical state of sandpile automaton models, Phys. Rev. Lett. 64 (1990); A. A. Járai, Sandpile models, Probab. Surv. 15 (2018)",
 loc="Járai, Sandpile models, arXiv:1401.0354, Section 3.3 (open problems)",
 why="The sandpile is the model of self-organized criticality, and its avalanche exponents are the predictions that theory was built to make. Dhar's burning bijection ties them to uniform spanning trees and loop-erased walk.",
 st="The infinite-volume stationary measure exists on Z^2 (Athreya–Járai 2004). Avalanches on Z^2 are finite almost surely, with a bound on the tail of the radius by a negative power of its logarithm (arXiv:2610.13940). In three dimensions the tail exponents of the radius, the number of distinct toppled vertices and the total number of topplings are found in arXiv:2605.19419. The two-dimensional exponents are open.",
 n="Statement revised after the w673 audit (14 Oct)."),
dict(id="T101", d="RW", t="Closed orbits in the Lorentz mirror model",
 s="At each vertex of Z^2 place, independently, a two-sided mirror along one of the two diagonals, each with probability p/2, or no mirror, with probability 1 − p. A light ray moving along the edges is reflected by mirrors and passes straight through empty vertices. Prove that for every p ∈ (0, 1) every orbit is periodic almost surely.",
 c="For p = 1 the statement follows from critical bond percolation on Z^2. In three dimensions the opposite is expected at small p: infinite orbits with positive probability.",
 src="T. W. Ruijgrok and E. G. D. Cohen, Deterministic lattice gas models, Phys. Lett. A 133 (1988); G. Grimmett, Percolation, 2nd ed. (Springer, 1999)",
 loc="Grimmett 1999; current statement in arXiv:2610.12460 (2026), abstract",
 why="The mirror model is the simplest deterministic walk in a random environment. Whether randomness forces the trajectory to be trapped in the plane, even when almost every site is empty, is a basic question about the line between deterministic and diffusive transport.",
 st="For p = 1 every orbit is closed, through critical bond percolation. Kozma and Sidoravicius showed that the probability that the ray reaches distance n is at least 1/(2n+1) at every mirror density (arXiv:1311.7437). arXiv:2610.12460 (2026) states that finiteness of all orbits on Z^2 is still a conjecture and builds infinite rays on other decorated planar graphs; arXiv:2609.14949 is a numerical study. Open for 0 < p < 1.",
 n="Status updated after the w673 audit (14 Oct)."),
dict(id="T102", d="RW", t="Random walk on the two-dimensional incipient infinite cluster",
 s="For simple random walk on Kesten's incipient infinite cluster of two-dimensional critical percolation, the quenched return probability is p_{2n}(0,0) = n^{−d_s/2+o(1)} and the mean exit time from the ball of radius r is r^{d_w+o(1)}. Determine the spectral dimension d_s and the walk dimension d_w; in particular decide whether the Alexander–Orbach value d_s = 4/3 holds.",
 c="Alexander and Orbach conjectured d_s = 4/3 in every dimension; the value is believed to fail in low dimensions, with numerical estimates near 1.32 in two dimensions (d_s = 2d_f/d_w with the resistance exponent 0.9826 of Grassberger, Physica A 262 (1999) 251). By the Einstein relation d_w = d_f + β_res with d_f = 91/48, so the question is the resistance exponent β_res; the Alexander–Orbach value would need β_res = 91/96.",
 src="S. Alexander and R. Orbach, Density of states on fractals: fractons, J. Physique Lett. 43 (1982); H. Kesten, Subdiffusive behavior of random walk on a random cluster, Ann. Inst. H. Poincaré Probab. Statist. 22 (1986)",
 why="Random walk on critical clusters is the model case of anomalous diffusion on random fractals. In two dimensions every geometric exponent of the cluster is known exactly but the walk exponent is not, so the problem tests whether conformal methods can reach the walk.",
 st="Kesten (1986) proved subdiffusivity on the 2D incipient infinite cluster. The Alexander–Orbach value holds in high dimensions (Kozma–Nachmias 2009), and for the critical level set of the cable-system Gaussian free field in high dimensions (Ganguly–Nam, arXiv:2403.02318). For the incipient infinite cluster of critical site percolation on the triangular lattice, Dankovic, Markering, Miller and Yuan (arXiv:2604.14122, Corollaries 1.3–1.4) prove that the exponents exist: 2(91/48)/(91/48 + β_res) for the almost-sure return probability and 91/48 + β_res for the mean exit time, with β_res not identified. The values are open.",
 n="Statement revised after the w673 audit (14 Oct)."),
dict(id="T103", d="RW", t="The growth exponent of three-dimensional loop-erased random walk",
 s="Let β be the growth exponent of loop-erased random walk on Z^3: the loop-erasure of simple random walk stopped on leaving the ball of radius n has n^{β+o(1)} steps. Determine β, which is also the Hausdorff dimension of the scaling limit.",
 c="Numerically β ≈ 1.624 (Wilson, Phys. Rev. E 82 (2010) 062102); no closed form is conjectured.",
 src="G. F. Lawler, Intersections of Random Walks (Birkhäuser, 1991); G. Kozma, The scaling limit of loop-erased random walk in three dimensions, Acta Math. 199 (2007)",
 why="Loop-erased walk gives the branches of the uniform spanning tree through Wilson's algorithm and is the simplest self-avoiding path with a scaling limit in three dimensions; β is the three-dimensional counterpart of the planar value 5/4 that comes from SLE(2).",
 st="In two dimensions β = 5/4 (Kenyon, Acta Math. 185 (2000); Masson, Electron. J. Probab. 14 (2009)). In three dimensions the scaling limit exists (Kozma 2007), β exists (Shiraishi 2018) and equals the Hausdorff dimension of the limit (Shiraishi, arXiv:1604.08091); β ∈ (1, 5/3], as stated in the abstract of arXiv:1604.08091, and the scaling limit has a Minkowski content (arXiv:2403.07256). An explicit β ≥ 1.0001 is proved in arXiv:2609.18643, and arXiv:2610.12047 characterizes the scaling limit, which gives its inversion invariance. The value is open.",
 n="Status updated after the w673 audit (14 Oct)."),
dict(id="T104", d="RW", t="Oliveira's conjecture on the mixing time of the interchange process",
 s="There is a universal constant C such that for every finite connected graph G on n vertices with nonnegative edge rates and every ε ∈ (0, 1/2), the total-variation mixing time of the interchange process on G satisfies t_mix^{IP}(ε) ≤ C log(n/ε) t_mix^{RW}(1/4), where t_mix^{RW} is the mixing time of a single random walk on G with the same rates.",
 c="The logarithm cannot be dropped: on the complete graph with rate 1/(n − 1) on each edge one walk mixes in time O(1), while the interchange process (random transpositions) needs time of order log n. The reverse inequality t_mix^{IP} ≥ t_mix^{RW} holds because the interchange process projects onto one walk. The conjecture is the mixing-time analogue of Aldous's spectral gap conjecture.",
 src="R. I. Oliveira, Mixing of the symmetric exclusion processes in terms of the corresponding single-particle random walk, Ann. Probab. 41 (2013)",
 loc="Oliveira, arXiv:1007.2669, Sections 1.1–1.2, pp. 2–3",
 why="The interchange process is the basic random walk on the symmetric group driven by a graph. Comparing its mixing with that of one particle is the natural way to carry single-particle bounds over to many-particle systems, and the spectral version became a well-known theorem.",
 st="Aldous's spectral gap conjecture was proved by Caputo, Liggett and Richthammer (2010). Oliveira (Ann. Probab. 41 (2013), arXiv:1007.2669) proved the bound for the exclusion process with any number of particles, and for the interchange process when a positive fraction of the sites is empty; the full interchange process, with every site labelled, is the open case. Hermon and Pymar compared k-particle exclusion with k independent walks up to a constant factor in several regimes, and within a log log n factor when k ≥ n^{Ω(1)} (arXiv:1808.10846).",
 n="Statement revised after the w673 audit (14 Oct)."),
dict(id="T105", d="RMT", t="The Berry–Tabor conjecture",
 s="For a generic completely integrable quantum system, for example the Laplacian on a flat torus R^2/L with a generic lattice L, the eigenvalues counted once for each pair ±v of dual-lattice vectors and unfolded have the local statistics of a Poisson process: every k-point correlation function and the nearest-neighbour spacing distribution converge to the Poisson ones.",
 c="The spectrum of a flat torus is symmetric under v ↦ −v, so without this identification every positive eigenvalue has even multiplicity and the spacing law has an atom at zero. Arithmetic tori such as the square torus have further multiplicities and are exceptions, so a theorem needs an explicit genericity (Diophantine) condition and must cover every local statistic, not only the pair correlation.",
 src="M. V. Berry and M. Tabor, Level clustering in the regular spectrum, Proc. R. Soc. Lond. A 356 (1977)",
 why="Berry–Tabor is the integrable counterpart of the Bohigas–Giannoni–Schmit conjecture (T089); together they say which spectra look random and how. For tori it becomes a question about the values of quadratic forms at integer points.",
 st="The pair correlation is Poisson for almost every flat 2-torus (Sarnak 1997) and for explicit Diophantine tori (Eskin–Margulis–Mozes, Ann. of Math. 161 (2005) 679); some higher correlations are known for almost every torus (VanderKam, Duke Math. J. 97 (1999); Comm. Math. Phys. 210 (2000)); Blomer, Bourgain, Radziwiłł and Rudnick (arXiv:1809.07881) obtain the triple correlation on average over tori and long gaps, and Marklof proved pair-correlation results for related integrable models (Ann. of Math. 158 (2003) 419). The spacing distribution is open for every individual torus.",
 n="Statement revised after the w673 audit (14 Oct).",
 loc="Blomer–Bourgain–Radziwiłł–Rudnick, arXiv:1809.07881, Sections 1.1–1.2"),
dict(id="T106", d="RMT", t="Berry's random wave conjecture",
 s="High-energy eigenfunctions of the Laplacian on a manifold or billiard with chaotic (ergodic and hyperbolic) dynamics behave locally like the isotropic Gaussian monochromatic wave: along a density-one subsequence, the eigenfunction φ_j viewed at the wavelength scale around a uniformly chosen point converges in law to the Gaussian field whose covariance in dimension two is J_0(|x − y|).",
 c="Precise formulations use local weak limits of eigenfunctions, normalized in L² by the volume and rescaled by the wavelength (a modern formulation is in arXiv:2305.14906); a density-one subsequence is needed because of exceptional modes (bouncing-ball modes of the stadium).",
 src="M. V. Berry, Regular and irregular semiclassical wavefunctions, J. Phys. A 10 (1977)",
 why="The random wave model underlies the predictions for nodal sets, L^p norms and value distributions of chaotic eigenfunctions, including the Bogomolny–Schmit percolation picture (T064). A proof would put the Gaussian picture of quantum chaos on firm ground.",
 st="Quantum ergodicity gives equidistribution of |φ_j|^2 at fixed scales along a density-one subsequence (Shnirelman 1974; Zelditch 1987; Colin de Verdière 1985), and arithmetic quantum unique ergodicity holds (Lindenstrauss 2006). Gaussian local statistics are not proved for any chaotic system; analogues are known for eigenvectors of random regular graphs (Backhausz–Szegedy, Ann. Probab. 47 (2019) 1677).",
 n="Status updated after the w673 audit (14 Oct)."),
dict(id="T107", d="RMT", t="The Fyodorov–Hiary–Keating conjecture",
 s="Let τ be uniform on [T, 2T]. Then max_{|h|≤1} log|ζ(1/2 + i(τ + h))| − (log log T − (3/4) log log log T) converges in distribution as T → ∞ to the limit law predicted by Fyodorov, Hiary and Keating.",
 c="The predicted limit is that of a log-correlated field: a Gumbel variable shifted by an independent random variable. The random-matrix analogue, for the characteristic polynomial of a Haar unitary matrix and more generally for the circular β-ensembles, is proved (Paquette–Zeitouni, arXiv:2209.06743).",
 src="Y. V. Fyodorov, G. A. Hiary and J. P. Keating, Freezing transition, characteristic polynomials of random matrices, and the Riemann zeta function, Phys. Rev. Lett. 108 (2012); Y. V. Fyodorov and J. P. Keating, Freezing transitions and extreme values: random matrix theory, ζ(1/2+it) and disordered landscapes, Philos. Trans. R. Soc. A 372 (2014)",
 why="It joins three subjects: extreme values of log-correlated fields, characteristic polynomials of random matrices, and the local maxima of the Riemann zeta function on the critical line. Its zeta form is a probabilistic statement about a number-theoretic object.",
 st="For circular β-ensembles the maximum is log N − (3/4) log log N + O_P(1) (Arguin–Belius–Bourgade 2017; Paquette–Zeitouni 2018; Chhaibi–Madaule–Najnudel 2018), and it converges in law to a Gumbel variable shifted by a derivative-martingale term (Paquette–Zeitouni, arXiv:2209.06743). For zeta, tightness of the recentred maximum and the order of its right tail are proved (Najnudel 2018; Arguin–Bourgade–Radziwiłł, arXiv:2007.00988 and arXiv:2307.00982). Convergence in law for zeta is open.",
 n="Statement revised after the w673 audit (14 Oct)."),
dict(id="T108", d="SM", t="The universal jump at the Berezinskii–Kosterlitz–Thouless transition",
 s="For the nearest-neighbour XY model on Z^2 (spins on the circle, energy −Σ cos(θ_x − θ_y)), (a) the helicity modulus Υ(β) exists in the thermodynamic limit, vanishes for β < β_BKT and jumps at the transition: β_BKT Υ(β_BKT+) = 2/π; and (b) at β_BKT the spin–spin correlation decays as |x|^{−1/4+o(1)}.",
 c="The two predictions are linked through Kosterlitz's renormalization picture, but neither is known to imply the other; logarithmic corrections are expected in the correlation at β_BKT.",
 src="D. R. Nelson and J. M. Kosterlitz, Universal jump in the superfluid density of two-dimensional superfluids, Phys. Rev. Lett. 39 (1977); J. Fröhlich and T. Spencer, The Kosterlitz–Thouless transition in two-dimensional abelian spin systems and the Coulomb gas, Comm. Math. Phys. 81 (1981)",
 why="BKT is the model of a topological phase transition, and the universal jump is its sharpest quantitative prediction, confirmed in helium films (Bishop–Reppy 1978). The rigorous theory establishes the transition but none of its universal features.",
 st="Power-law decay at low temperature (Fröhlich–Spencer 1981) and exponential decay at high temperature give the transition; newer proofs go through delocalization of height functions (Lammers, arXiv:2012.09687, Probab. Theory Related Fields; van Engelenburg–Lis, arXiv:2110.09465; Aizenman–Harel–Peled–Shapiro, arXiv:2110.09498), and arXiv:2608.04972 extends phase-existence results to disordered and generalized XY models. For the Villain model Aizenman–Harel–Peled–Shapiro (arXiv:2110.09498) prove non-summable decay of correlations at every temperature where the dual integer-valued height function delocalizes, and the same for the XY model through its Bessel height function. Both (a) and (b) are open for the XY model.",
 n="Statement revised after the w673 audit (14 Oct)."),
dict(id="T109", d="SM", t="A single phase transition for the hard-core model on Z^2",
 s="For the hard-core lattice gas on Z^2 (independent sets weighted by λ^{|I|}) there is a critical activity λ_c such that the Gibbs measure is unique for λ < λ_c and there are two distinct checkerboard Gibbs measures for λ > λ_c; numerically λ_c ≈ 3.7962.",
 c="The model is not known to be monotone in λ, so uniqueness at one activity does not give uniqueness below it; a single transition point is part of the claim.",
 src="D. S. Gaunt and M. E. Fisher, Hard-sphere lattice gases. I. Plane-square lattice, J. Chem. Phys. 43 (1965); R. J. Baxter, I. G. Enting and S. K. Tsang, Hard-square lattice gas, J. Stat. Phys. 22 (1980)",
 why="Hard squares is the simplest lattice model of a freezing transition (compare hard spheres, T080) and a standard test case for sampling algorithms; the gap between the proved uniqueness and coexistence regimes has resisted many methods. Baxter's exact solution covers hard hexagons, not hard squares.",
 st="Uniqueness is proved for λ < 2.538 (Sinclair–Srivastava–Štefankovič–Yin 2017) and coexistence for λ > 5.3506 (Blanca–Chen–Galvin–Randall–Tetali, arXiv:1611.01115); coexistence at large λ goes back to Peierls arguments (Dobrushin 1968). Absence of complex zeros of the partition function up to the connective-constant threshold λ_c(σ) is proved in arXiv:2604.02746. The high-dimensional critical fugacity d^{−1+o(1)} (Hadas–Peled, arXiv:2603.27144; T140, retired) does not bear on Z^2. A single transition and the value of λ_c are open.",
 n="Status updated after the w673 audit (14 Oct)."),
dict(id="T110", d="SM", t="Long-range order for proper 3-colourings of Z^3 (Kotecký's conjecture)",
 s="For a uniformly random proper 3-colouring of the box {−L, …, L}^3 in Z^3 whose even boundary vertices are coloured 0 (the zero-temperature antiferromagnetic 3-state Potts model), there is c > 0 such that every even vertex far from the boundary has colour 0 with probability at least 1/3 + c, uniformly in L: the boundary's sublattice order survives in the bulk.",
 c="In two dimensions the model maps to a height function and is expected to be disordered; the conjecture is that three dimensions is already ordered. Classifying the extremal Gibbs measures of maximal entropy (six are expected) would be a further step.",
 src="Kotecký's conjecture as reported in D. Galvin, J. Kahn, D. Randall and G. B. Sorkin, Phase coexistence and torpid mixing in the 3-coloring model on Z^d, SIAM J. Discrete Math. 29 (2015) 1223–1244",
 why="It is the cleanest open case of order created by entropy alone at zero temperature in a physical dimension, and it decides whether Glauber dynamics for 3-colourings of Z^3 mixes slowly.",
 st="Long-range order is proved in high dimensions, with an error exp(−cd) controlled by the dimension rather than the box size (Galvin–Kahn–Randall–Sorkin, arXiv:1210.4232; Peled, High-dimensional Lipschitz functions are typically flat, Ann. Probab. 45 (2017)), and for q-colourings in high dimensions (Peled–Spinka, arXiv:1808.03597). Three dimensions is open.",
 n="Statement revised after the w673 audit (14 Oct). Fame borderline in that audit; kept for now."),
]
